import type { HTMLAttributes } from 'react'
import { cn } from '@/react/lib/cn'

// A box that keeps its shape as it grows (CSS aspect-ratio), for a picture or a window that must not reflow: the blog
// card's 5:4 picture, the hero's 2:1 frame. `ratio` is width over height; the content fills it.
export interface AspectRatioProps extends HTMLAttributes<HTMLDivElement> {
  /** Width over height. */
  ratio?: number
}

export function AspectRatio({ ratio = 1, className, style, children, ...rest }: AspectRatioProps) {
  return (
    <div data-ds="aspect-ratio" className={cn('relative w-full overflow-hidden', className)} style={{ ...style, aspectRatio: String(ratio) }} {...rest}>
      {children}
    </div>
  )
}

export default AspectRatio

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

import { html, type PropertyValues } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// AspectRatio.vue as <conare-aspect-ratio>: a box that keeps its shape as it grows (CSS aspect-ratio), for a picture or
// a window that must not reflow: the blog card's 5:4 picture, the hero's 2:1 frame. `ratio` is width over height; the
// content fills it. The host is the box (aspect-ratio.css), so a class on it (a ground, a width) lands as a class on
// <AspectRatio> does.

/**
 * @summary A box that keeps its shape as it grows.
 * @slot - What fills it (position it absolutely to fill the box).
 */
export class AspectRatio extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { ratio: { type: Number } }

	/** Width over height. */
	ratio = 1

	protected updated(changed: PropertyValues) {
		super.updated(changed)
		// As Vue's :style on the root: the host is the root.
		if (changed.has('ratio')) this.style.aspectRatio = String(this.ratio)
	}

	render() {
		return html`<slot></slot>`
	}
}

define('aspect-ratio', AspectRatio)

/* The host is the box (AspectRatio.vue's root div), so a class on <conare-aspect-ratio> lands on it as a class on
   <AspectRatio> does. */
:host { @apply relative block w-full overflow-hidden; }
